#!/usr/bin/env bash
# Build the bench PRGs with llvm-mos (WSL Ubuntu-24.04): bash target-c64/bench/build.sh
#   dist/bench.prg    the milestone 2 kernel bench (tools/bench_cycles.py)
#   dist/iobench.prg  the C64U I/O timing bench (iobench.S is generated by tools/iobench.py)
set -euo pipefail
cd "$(dirname "$0")"
CLANG="${MOS_CLANG:-$HOME/.local/llvm-mos/bin/mos-c64-clang}"
mkdir -p ../../dist
"$CLANG" -Os -o ../../dist/bench.prg main.c bench.S -Wl,--Map=../../dist/bench.map
"$HOME/.local/llvm-mos/bin/llvm-objdump" -d ../../dist/bench.prg.elf > ../../dist/bench.lst
echo built ../../dist/bench.prg
"$CLANG" -Os -o ../../dist/iobench.prg iomain.c iobench.S -Wl,--Map=../../dist/iobench.map
"$HOME/.local/llvm-mos/bin/llvm-objdump" -d ../../dist/iobench.prg.elf > ../../dist/iobench.lst
echo built ../../dist/iobench.prg
